// claim_sanitizer.go - core filtering logic
func SanitizeClaims(claims map[string]string) map[string]string {
  // drop exact keys known to contain PII
  delete(claims, "operator_email")
  delete(claims, "operator_raw_jwt")
  // pseudonymize operator_id when configured
  if v, ok := claims["operator_id"]; ok {
    claims["operator_id_hash"] = hashID(v)
    delete(claims, "operator_id")
  }
  return claims
}
